<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Pterodactyl\Services\Dezerx\Uploads; use Pterodactyl\Services\Dezerx\Settings; use Pterodactyl\Services\Dezerx\Appearance; use Pterodactyl\Http\Controllers\Controller; class AppearanceController extends Controller { private function patch(array $patch): void { Settings::put( Appearance::SETTING_KEY, array_replace(Settings::get(Appearance::SETTING_KEY) ?? [], $patch), ); } public function tokens(Request $request): JsonResponse { $tokens = [ 'dark' => Appearance::sanitiseTokens($request->input('dark', [])), 'light' => Appearance::sanitiseTokens($request->input('light', [])), ]; $this->patch(['tokens' => $tokens]); return new JsonResponse(['tokens' => $tokens]); } public function logo(Request $request): JsonResponse { $mode = (string) $request->input('mode', 'text'); $mark = Appearance::path($request->input('mark')); $this->patch([ 'logo' => [ 'mode' => in_array($mode, Appearance::LOGO_MODES, true) ? $mode : 'text', 'text' => mb_substr(trim((string) $request->input('text', '')), 0, 40), 'image' => Appearance::path($request->input('image')), 'imageLight' => Appearance::path($request->input('imageLight')), 'mark' => $mark === '' ? null : $mark, 'alt' => mb_substr(trim((string) $request->input('alt', '')), 0, 80), ], ]); return new JsonResponse(['logo' => Appearance::logo()]); } public function uploadLogo(Request $request): JsonResponse { return new JsonResponse(['path' => Uploads::store($request, 'logos')]); } public function presets(Request $request): JsonResponse { $presets = Appearance::sanitisePresets((array) $request->input('presets', [])); $ids = array_column($presets, 'id'); $default = Appearance::slug((string) $request->input('defaultPreset', '')); $this->patch([ 'presets' => $presets, 'defaultPreset' => in_array($default, $ids, true) ? $default : ($ids[0] ?? 'default'), 'allowUserPresets' => (bool) $request->input('allowUserPresets', true), ]); return new JsonResponse(['presets' => $presets]); } public function fonts(Request $request): JsonResponse { $fonts = []; foreach (Appearance::FONT_SLOTS as $slot) { $fonts[$slot] = Appearance::fontForSlot($request->input($slot), $slot); } $this->patch(['fonts' => $fonts]); return new JsonResponse(['fonts' => $fonts]); } } 